window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-11b3b6c1f2d4d1b4"]={"versions": [{"id": "FIG-11b3b6c1f2d4d1b4", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Kommunikations- und Topologiediagramm der AUTOSAR Classic Platform (System Template). Das Diagramm illustriert auf Systemebene die Netzwerkkommunikation und den Frame-Austausch zwischen zwei Steuergeräten (ECUs) im Kontext von SW-Component-Inklusions- und Signal-Mapping-Regeln für das ECU-Extract.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Steuergeräte-Knoten und zwei strukturierte Übertragungsrahmen:</p>\n<ul class=\"fig-list\"><li><strong>ECU A</strong>: Sender von FrameX und Empfänger von FrameY; visuell durch orangefarbene Füllung hervorgehoben.\n</li><li><strong>ECU B</strong>: Empfänger von FrameX und Sender von FrameY; visuell durch hellorange/beige Füllung dargestellt.\n</li><li><strong>FrameX</strong>: Gerichteter Kommunikationsrahmen von ECU A nach ECU B, unterteilt in ein beschriftetes Kopffeld (<code>FrameX</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (orangefarben).\n</li><li><strong>FrameY</strong>: Gerichteter Kommunikationsrahmen von ECU B nach ECU A, unterteilt in ein beschriftetes Kopffeld (<code>FrameY</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (hellbeige).\n</li><li><strong>Schnittstellen/Kanten</strong>: Gerichtete Pfeilverbindungen symbolisieren die unidirektionale Übertragung auf dem gemeinsamen Übertragungsmedium.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner, bidirektionaler Nachrichtenaustausch über das Kommunikationsnetzwerk:</p>\n<ol class=\"fig-list\"><li><code>ECU A</code> sendet <code>FrameX</code> über den Bus an <code>ECU B</code>.\n</li><li>Gegenläufig sendet <code>ECU B</code> <code>FrameY</code> über den Bus an <code>ECU A</code>.\n</li></ol>\n<p class=\"fig-p\">Beide Frames transportieren aggregierte PDU- bzw. Signalstrukturen (dargestellt durch die segmentierten Felder) zwischen den Software-Komponenten beider Steuergeräte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als Minimalbeispiel zur Erläuterung der Inklusionskriterien im ECU-Extract:</p>\n<ul class=\"fig-list\"><li>Für die Generierung eines ECU-Extracts (z. B. für <code>ECU A</code>) müssen diejenigen Frames, PDUs und Signale inkludiert werden, bei denen das betreffende Steuergerät als Sender oder Empfänger fungiert.\n</li><li>Bei Signalen, die aus Software-Komponenten stammen oder an diese übermittelt werden, entscheidet das Komponenten- und Daten-Mapping (<code>SwCompToEcuMapping</code>, <code>DataMapping</code>), welche Kommunikationsressourcen (Frames, I-PDUs, Signals) in das jeweilige Steuergeräte-Modell übernommen werden müssen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-10cc4a0d1e331aaf", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Kommunikations- und Topologiediagramm der AUTOSAR Classic Platform (System Template). Das Diagramm illustriert auf Systemebene die Netzwerkkommunikation und den Frame-Austausch zwischen zwei Steuergeräten (ECUs) im Kontext von SW-Component-Inklusions- und Signal-Mapping-Regeln für das ECU-Extract.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Steuergeräte-Knoten und zwei strukturierte Übertragungsrahmen:</p>\n<ul class=\"fig-list\"><li><strong>ECU A</strong>: Sender von FrameX und Empfänger von FrameY; visuell durch orangefarbene Füllung hervorgehoben.\n</li><li><strong>ECU B</strong>: Empfänger von FrameX und Sender von FrameY; visuell durch hellorange/beige Füllung dargestellt.\n</li><li><strong>FrameX</strong>: Gerichteter Kommunikationsrahmen von ECU A nach ECU B, unterteilt in ein beschriftetes Kopffeld (<code>FrameX</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (orangefarben).\n</li><li><strong>FrameY</strong>: Gerichteter Kommunikationsrahmen von ECU B nach ECU A, unterteilt in ein beschriftetes Kopffeld (<code>FrameY</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (hellbeige).\n</li><li><strong>Schnittstellen/Kanten</strong>: Gerichtete Pfeilverbindungen symbolisieren die unidirektionale Übertragung auf dem gemeinsamen Übertragungsmedium.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner, bidirektionaler Nachrichtenaustausch über das Kommunikationsnetzwerk:</p>\n<ol class=\"fig-list\"><li><code>ECU A</code> sendet <code>FrameX</code> über den Bus an <code>ECU B</code>.\n</li><li>Gegenläufig sendet <code>ECU B</code> <code>FrameY</code> über den Bus an <code>ECU A</code>.\n</li></ol>\n<p class=\"fig-p\">Beide Frames transportieren aggregierte PDU- bzw. Signalstrukturen (dargestellt durch die segmentierten Felder) zwischen den Software-Komponenten beider Steuergeräte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als Minimalbeispiel zur Erläuterung der Inklusionskriterien im ECU-Extract:</p>\n<ul class=\"fig-list\"><li>Für die Generierung eines ECU-Extracts (z. B. für <code>ECU A</code>) müssen diejenigen Frames, PDUs und Signale inkludiert werden, bei denen das betreffende Steuergerät als Sender oder Empfänger fungiert.\n</li><li>Bei Signalen, die aus Software-Komponenten stammen oder an diese übermittelt werden, entscheidet das Komponenten- und Daten-Mapping (<code>SwCompToEcuMapping</code>, <code>DataMapping</code>), welche Kommunikationsressourcen (Frames, I-PDUs, Signals) in das jeweilige Steuergeräte-Modell übernommen werden müssen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3a4e4314a882809c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Kommunikations- und Topologiediagramm der AUTOSAR Classic Platform (System Template). Das Diagramm illustriert auf Systemebene die Netzwerkkommunikation und den Frame-Austausch zwischen zwei Steuergeräten (ECUs) im Kontext von SW-Component-Inklusions- und Signal-Mapping-Regeln für das ECU-Extract.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Steuergeräte-Knoten und zwei strukturierte Übertragungsrahmen:</p>\n<ul class=\"fig-list\"><li><strong>ECU A</strong>: Sender von FrameX und Empfänger von FrameY; visuell durch orangefarbene Füllung hervorgehoben.\n</li><li><strong>ECU B</strong>: Empfänger von FrameX und Sender von FrameY; visuell durch hellorange/beige Füllung dargestellt.\n</li><li><strong>FrameX</strong>: Gerichteter Kommunikationsrahmen von ECU A nach ECU B, unterteilt in ein beschriftetes Kopffeld (<code>FrameX</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (orangefarben).\n</li><li><strong>FrameY</strong>: Gerichteter Kommunikationsrahmen von ECU B nach ECU A, unterteilt in ein beschriftetes Kopffeld (<code>FrameY</code>) sowie drei aufeinanderfolgende unbeschriftete Segmente/Signal-Payload-Slots (hellbeige).\n</li><li><strong>Schnittstellen/Kanten</strong>: Gerichtete Pfeilverbindungen symbolisieren die unidirektionale Übertragung auf dem gemeinsamen Übertragungsmedium.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner, bidirektionaler Nachrichtenaustausch über das Kommunikationsnetzwerk:</p>\n<ol class=\"fig-list\"><li><code>ECU A</code> sendet <code>FrameX</code> über den Bus an <code>ECU B</code>.\n</li><li>Gegenläufig sendet <code>ECU B</code> <code>FrameY</code> über den Bus an <code>ECU A</code>.\n</li></ol>\n<p class=\"fig-p\">Beide Frames transportieren aggregierte PDU- bzw. Signalstrukturen (dargestellt durch die segmentierten Felder) zwischen den Software-Komponenten beider Steuergeräte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als Minimalbeispiel zur Erläuterung der Inklusionskriterien im ECU-Extract:</p>\n<ul class=\"fig-list\"><li>Für die Generierung eines ECU-Extracts (z. B. für <code>ECU A</code>) müssen diejenigen Frames, PDUs und Signale inkludiert werden, bei denen das betreffende Steuergerät als Sender oder Empfänger fungiert.\n</li><li>Bei Signalen, die aus Software-Komponenten stammen oder an diese übermittelt werden, entscheidet das Komponenten- und Daten-Mapping (<code>SwCompToEcuMapping</code>, <code>DataMapping</code>), welche Kommunikationsressourcen (Frames, I-PDUs, Signals) in das jeweilige Steuergeräte-Modell übernommen werden müssen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-11b3b6c1f2d4d1b4", "to": "FIG-10cc4a0d1e331aaf", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-10cc4a0d1e331aaf", "to": "FIG-3a4e4314a882809c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
